from pathlib import Path
import shutil,json,hashlib,csv
R=Path(__file__).resolve().parents[3];O=Path(__file__).resolve().parent
C=R/'experiments/2026-10-13-xy-infinite-volume';S=R/'experiments/2026-10-15-xy-3d-spin-dimension'
P=C/'d2-d3-d4-d5-attained-with-tree-20261014-182254';T=C/'d3-d4-phase-boundary-delivery-20261013-220038'
F=O/'figures';F.mkdir(exist_ok=True);D=O/'numerical-data';D.mkdir(exist_ok=True)
entries=[]
def add(stem,new,title,caption):
 item={'id':new,'title':title,'caption':caption,'source':str(stem.relative_to(R)),'files':{}}
 for ext in ['png','pdf','svg']:
  src=stem.with_suffix('.'+ext);dst=F/(new+'.'+ext);shutil.copy2(src,dst)
  item['files'][ext]={'name':dst.name,'sha256':hashlib.sha256(dst.read_bytes()).hexdigest()}
 entries.append(item)
add(P/'combined-MC-vs-tree-level','01-phase-boundaries-all-dimensions','Phase boundaries: d = 2, 3, 4, 5','Unconnected MC extrapolations versus the full tree instability criterion (2d-1)v1=1. Dark bars: conditional MC95. Pale bars: descriptive sensitivity unions, not certified total confidence intervals. Beta=0 endpoints have horizontal bars; fixed-epsilon points have vertical bars. The open d=5 square at epsilon/pi=1 is a rejected-fit diagnostic, not an accepted critical coupling. Axes differ across panels.')
for d in range(2,6):
 add(P/f'd{d}-MC-vs-tree-level',f'0{d}-phase-boundary-d{d}',f'Phase boundary: d = {d}','Unconnected MC extrapolations versus the full tree criterion. Dark bars are conditional MC95; pale bars are descriptive sensitivity unions, not certified total confidence intervals. Beta=0 endpoints have horizontal bars; fixed-epsilon points have vertical bars.'+(' The open square at epsilon/pi=1 is a rejected-fit diagnostic, not an accepted critical coupling.' if d==5 else '')+(' In d=2, N=512 is available only at representative slices/endpoints; absolute BKT accuracy is not certified.' if d==2 else ''))
add(T/'d3-finite-size-extrapolations','06-finite-size-d3','Finite-size transition fits: d = 3','Binder U=1/4 pseudo-critical locations, plotted against N^(-1/nu), nu=0.67169. Interpolation, size cuts and correction fits are sensitivity assumptions. This is the phase-boundary analysis, not the later common-xi scaling-dimension estimator.')
add(T/'d4-finite-size-extrapolations','07-finite-size-d4','Finite-size transition fits: d = 4','Binder U=1/4 locations use the leading N^-2 (ln N)^(-1/10) shift coordinate. Uniform primary positive-beta cut N>=10 was chosen after inspecting pilot residuals. Fits and error coverage remain conditional.')
add(P/'d5-finite-size-diagnostics','08-finite-size-d5','Finite-size transition diagnostics: d = 5','Dedicated above-upper-critical-dimension leading N^-5/2 shift, with additive N^-3 stress tests. Quarter-Binder is a fixed ordered-side criterion, not a universal finite-box critical value. Rejected fits and zero-degree-of-freedom diagnostics must not be presented as validated extrapolations.')
add(S/'four-size-xi-crossing-20261015-223504/four-size-xi-crossing','09-four-size-correlation-length-crossing','3D beta=0: four sizes on one plot','Measured xi/L for L=24,32,48,64 with independent broad-window quadratic response fits. No common crossing or critical xi/L is imposed. Bars/bands are conditional MC95. Finite-size curves need not cross at exactly one epsilon.')
add(S/'dimension-readout-plots-20261015-224446/01-rms-magnetization-slope','10-magnetization-slope','3D beta=0: reading off the spin dimension','At the exactly sampled epsilon/pi=0.80075, RMS magnetization scales approximately as L^-Delta_eff over L=24,32,48,64. Correlated fit gives Delta_eff=0.51942 +/- 0.00795 statistical SD. This is a representative fixed-epsilon finite-size slope, not a calibrated infinite-volume CFT result.')
add(S/'dimension-readout-plots-20261015-224446/02-effective-dimension-curves','11-effective-dimension-curves','3D beta=0: effective dimensions across the scan','Delta_eff(L,2L;q)=-ln(<m2>_2L/<m2>_L)/(2 ln2), evaluated at common q. Four overlapping size pairs retain shared-source covariance. Grey band is a descriptive union of finite-pair xi/L crossing intervals, not a thermodynamic epsilon_c confidence interval.')
add(S/'representative-analysis-plots-20261015-215950/02-correlated-size-extrapolation','12-spin-dimension-size-extrapolation','3D beta=0: conditional size extrapolations','Correlated extrapolations of common-xi quotient dimensions with fixed Wilson-Fisher-informed correction exponent omega=0.789. These illustrate model and size-cut sensitivity; no final Delta +/- stat +/- sys is established. Low/missing-validity pairs are not silently accepted.')
add(S/'representative-analysis-plots-20261015-215950/03-analysis-sensitivity','13-spin-dimension-analysis-sensitivity','3D beta=0: analysis sensitivity','Local response model/window, late-cut, block-length and independent-start sensitivity. A stable selected family is not proof of complete mixing or total uncertainty coverage; rejected responses and unresolved alternatives are retained in the source analysis.')
(O/'figure-captions.txt').write_text('\n\n'.join(f"{x['id']} | {x['title']}\n{x['caption']}\nSource: {x['source']}" for x in entries)+'\n')
(O/'figure-manifest.json').write_text(json.dumps(entries,indent=2))
for p,new in [(P/'phase-boundary-locations.csv','phase-boundary-locations.csv'),(P/'d5-finite-size-locations.csv','d5-finite-size-locations.csv'),(P/'prior-unresolved-locations.csv','d2-d3-d4-unresolved-locations.csv'),(P/'d5-unresolved-locations.csv','d5-unresolved-locations.csv'),(S/'dimension-readout-plots-20261015-224446/plotted-data.json','spin-dimension-readout-data.json'),(S/'four-size-xi-crossing-20261015-223504/plotted-data.json','four-size-xi-data.json'),(S/'local-xi-response-20261015-213702/refined-common-coupling-summary.txt','spin-dimension-analysis-summary.txt')]:shutil.copy2(p,D/new)
with (D/'spin-dimension-selected-estimates.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['estimator','Delta_effective_or_conditional','statistical_SD','qualification']);w.writerows([['common xi/L 24:48 broad quadratic',.515981,.002921,'finite pair, conditional response model'],['common xi/L 32:64 broad quadratic',.519027,.003260,'finite pair, correlated with 24:48'],['fixed q=.80075 RMS slope L24..64',.5194207729,.0079466095,'fixed q finite-size slope, not epsilon_c extrapolation'],['omega=.789 size extrapolation minimum pair L8',.523209,.003462,'WF-informed correction assumption; not preferred final Delta'],['omega=.789 size extrapolation minimum pair L12',.518340,.006158,'WF-informed correction assumption; no calibrated systematic error']])
print(f'Collected {len(entries)} figures in three formats.')
